package com.spendwise.auth; import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService service;public AuthController(AuthService s){service=s;}public record RegisterRequest(@NotBlank @Size(max=80)String name,@NotBlank @Email @Size(max=254)String email,@NotBlank @Size(min=8,max=72)String password){}public record LoginRequest(@NotBlank @Email @Size(max=254)String email,@NotBlank @Size(max=72)String password){}
@PostMapping("/register")public Map<String,Object> register(@Valid @RequestBody RegisterRequest r){return service.register(r.name(),r.email(),r.password());}@PostMapping("/login")public Map<String,Object> login(@Valid @RequestBody LoginRequest r){return service.login(r.email(),r.password());}}